// Raggruppa per cliente: UN SOLO messaggio per cliente al giorno,
// anche se mancano documenti per piu' scadenze diverse.

const scadenze = $('Scadenze entro 10 giorni').all().map(i => i.json);
const documenti = $('Documenti mancanti').all().map(i => i.json);
const clienti   = $('Anagrafica clienti').all().map(i => i.json);

const oggi = new Date();
const giorniA = (d) => Math.ceil((new Date(d) - oggi) / 86400000);
const oggiISO = oggi.toISOString().slice(0, 10);

const byId = Object.fromEntries(clienti.map(c => [c.client_id, c]));
const out = [];

for (const cliente of clienti) {
  // GUARDRAIL 1: clienti con invii bloccati -> solo promemoria interno
  if (cliente.blocco_invii_automatici) continue;

  const docs = documenti.filter(d => d.client_id === cliente.client_id && d.obbligatorio);
  if (docs.length === 0) continue;

  // GUARDRAIL 2: mai due solleciti allo stesso cliente nello stesso giorno
  const sollecitatoOggi = docs.some(d => d.data_ultimo_sollecito === oggiISO);
  if (sollecitatoOggi) continue;

  const scad = scadenze.filter(s => s.client_id === cliente.client_id);
  if (scad.length === 0) continue;

  const prossima = scad.sort((a, b) => new Date(a.data_scadenza) - new Date(b.data_scadenza))[0];
  const giorni = giorniA(prossima.data_scadenza);

  // Catena di escalation: T-10 / T-5 / T-2. Clienti poco puntuali partono prima.
  const anticipo = (cliente.puntualita_score || 3) <= 2 ? 15 : 10;
  const tappe = [anticipo, 5, 2];
  if (!tappe.includes(giorni)) continue;

  const livello = giorni >= 10 ? 1 : (giorni === 5 ? 2 : 3);

  out.push({
    json: {
      client_id: cliente.client_id,
      ragione_sociale: cliente.ragione_sociale,
      referente_nome: cliente.referente_nome,
      referente_email: cliente.referente_email,
      canale: cliente.canale_preferito || 'email',
      tono: cliente.tono_comunicazione || 'cordiale',
      livello_sollecito: livello,
      giorni_alla_scadenza: giorni,
      adempimento: prossima.descrizione,
      periodo: prossima.periodo_riferimento,
      data_scadenza: prossima.data_scadenza,
      documenti_mancanti: docs.map(d => ({ doc_id: d.doc_id, tipo: d.tipo, periodo: d.periodo })),
      // GUARDRAIL 3: dal terzo sollecito serve approvazione umana
      richiede_approvazione: livello >= 3
    }
  });
}

return out;

// Compone l'email a partire da templates/email/01-sollecito-documenti.md.
// REGOLA: nessun segnaposto puo' restare vuoto. Se un dato manca, l'email
// non si genera e si apre un'anomalia.

const etichette = {
  estratto_conto:  'estratto conto bancario',
  fatture_attive:  'fatture emesse',
  fatture_passive: 'fatture di acquisto',
  corrispettivi:   'corrispettivi',
  prima_nota:      'prima nota',
  contratti:       'contratti',
  f24_pagato:      'ricevuta di pagamento F24',
  altro:           'altra documentazione'
};

const apertura = {
  1: (n) => `Buongiorno ${n},`,
  2: (n) => `Buongiorno ${n},`,
  3: (n) => `Buongiorno ${n},`
};

const corpo = {
  1: 'per completare la lavorazione ci mancano ancora questi documenti:',
  2: 'torniamo sulla richiesta: mancano ancora questi documenti e la scadenza si avvicina.',
  3: 'la scadenza e\' fra pochi giorni e ci mancano ancora questi documenti. Ci servono per procedere in tempo.'
};

const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const mancanti = (d.documenti_mancanti || [])
    .map(x => `• ${etichette[x.tipo] || x.tipo} — periodo ${x.periodo}`)
    .join('\n');

  const campiObbligatori = [d.referente_nome, d.referente_email, d.adempimento, d.data_scadenza];
  if (campiObbligatori.some(v => !v) || !mancanti) {
    out.push({ json: { ...d, errore: 'dati_mancanti', invia: false } });
    continue;
  }

  const data = new Date(d.data_scadenza).toLocaleDateString('it-IT');
  const oggetto = `${d.ragione_sociale} · documenti mancanti per ${d.adempimento} · scadenza ${data}`;

  const testo = [
    apertura[d.livello_sollecito](d.referente_nome),
    '',
    corpo[d.livello_sollecito],
    '',
    mancanti,
    '',
    `Servono per: ${d.adempimento} — periodo ${d.periodo}, in scadenza il ${data} (fra ${d.giorni_alla_scadenza} giorni).`,
    '',
    'Puoi rispondere direttamente a questa email allegando i file, oppure caricarli qui: REPLACE_LINK_UPLOAD',
    '',
    'Grazie,',
    'Studio'
  ].join('\n');

  out.push({ json: { ...d, oggetto, testo, invia: true } });
}

return out;
